import { Table, GenericColumn, StringColumn, BooleanColumn } from '@servicenow/sdk/core'

export const sys_script_email = Table({
    allowWebServiceAccess: true,
    extends: 'sys_metadata',
    label: 'Email Script',
    name: 'sys_script_email',
    schema: {
        sys_id: GenericColumn({
            columnType: 'GUID',
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
        name: StringColumn({
            label: [
                {
                    hint: 'Name of script',
                    label: 'Name',
                    plural: 'Names',
                    language: 'en',
                },
            ],
            maxLength: 100,
            unique: true,
        }),
        script: GenericColumn({
            columnType: 'script_plain',
            default: `(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {

          // Add your code here

})(current, template, email, email_action, event);`,
            label: [
                {
                    hint: 'Script contents',
                    label: 'Script',
                    plural: 'Scripts',
                    language: 'en',
                },
            ],
            maxLength: 4000,
        }),
        new_lines_to_html: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'For backwards-compatibility with older scripts, automatically convert newlines such as template.print("\n") into HTML by wrapping lines with "<div>...</div>"',
                    label: 'Newlines to HTML',
                    plural: 'Newlines to HTMLs',
                    language: 'en',
                },
            ],
        }),
    },
    textIndex: true,
})
